class Solution:
    def minimumChairs(self, s: str) -> int:
        ans = cur = 0
        for c in s:
            cur += 1 if c == 'E' else -1
            ans = max(ans, cur)
        return ans

count-pairs-that-form-a-complete-day-i:
class Solution:
    def countCompleteDayPairs(self, hours: List[int]) -> int:
        from collections import Counter
        c = Counter(h % 24 for h in hours)
        ans = 0
        for k, v in c.items():
            if k == 0 or k == 12:
                ans += v*(v-1)//2
            elif k < 12 and (24-k) in c:
                ans += v*c[24-k]
        # divide each counted twice
        return ans // 2

check-if-grid-satisfies-conditions:
class Solution:
    def satisfiesConditions(self, grid: List[List[int]]) -> bool:
        R, C = len(grid), len(grid[0])
        for i in range(R):
            for j in range(C):
                if i+1 < R and grid[i][j] != grid[i+1][j]: return False
                if j+1 < C and grid[i][j] == grid[i][j+1]: return False
        return True

make-a-square-with-the-same-color:
class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        for i in range(2):
            for j in range(2):
                w = b = 0
                for di in range(2):
                    for dj in range(2):
                        if grid[i+di][j+dj] == 'W': w +=  1
                        else: b +=  1
                if w == 1 or b ==  1:
                    return True
        return False

