maximum-area-of-longest-diagonal-rectang:
class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        best = -1; best_area = -1
        for w, h in dimensions:
            d = w*w + h*h
            a = w*h
            if d > best or (d == best and a > best_area):
                best = d; best_area = a
        return best_area

check-if-bitwise-or-has-trailing-zeros:
class Solution:
    def hasTrailingZeros(self, nums: List[int]) -> bool:
        return sum(1 for x in nums if x % 2 ==  0) >= 2

minimum-number-game:
class Solution:
    def numberGame(self, nums: List[int]) -> List[int]:
        nums.sort()
        for i in range(0, len(nums)-1, 2):
            nums[i], nums[i+1] = nums[i+1], nums[i]
        return nums

find-the-peaks:
class Solution:
    def findPeaks(self, mountain: List[int]) -> List[int]:
        return [i for i in range(1, len(mountain)-1) if mountain[i] > mountain[i-1] and mountain[i] > mountain[i+1]]

